"""Port interfaces for decoupling core logic from adapters (DB, config, API)."""
from abc import ABC, abstractmethod
from datetime import datetime
from typing import Dict, List, Optional

from .models import Coin, Pair, ScoutHistory, Trade


class DatabaseInterface(ABC):
    """Port for database operations (abstraction over database.py)."""

    @abstractmethod
    def set_coins(self, symbols: List[str]) -> None:
        ...

    @abstractmethod
    def get_coins(self, only_enabled: bool = True) -> List[Coin]:
        ...

    @abstractmethod
    def get_coin(self, coin: Coin) -> Coin:
        ...

    @abstractmethod
    def set_current_coin(self, coin: Coin) -> None:
        ...

    @abstractmethod
    def get_current_coin(self) -> Optional[Coin]:
        ...

    @abstractmethod
    def get_pairs_from(self, from_coin: Coin, only_enabled: bool = True) -> List[Pair]:
        ...

    @abstractmethod
    def log_scout(
        self,
        pair: Pair,
        target_ratio: float,
        current_coin_price: float,
        other_coin_price: float,
    ) -> None:
        ...


class ConfigInterface(ABC):
    """Port for configuration access (abstraction over config.py)."""

    @abstractmethod
    def get_bridge(self) -> Coin:
        ...

    @abstractmethod
    def get_bridge_symbol(self) -> str:
        ...

    @abstractmethod
    def get_supported_coin_list(self) -> List[str]:
        ...

    @abstractmethod
    def get_scout_margin(self) -> float:
        ...

    @abstractmethod
    def get_scout_multiplier(self) -> float:
        ...

    @abstractmethod
    def get_use_margin(self) -> str:
        ...

    @abstractmethod
    def get_scout_sleep_time(self) -> int:
        ...


class BinanceAPIManagerInterface(ABC):
    """Port for Binance API interactions (abstraction over binance_api_manager.py)."""

    @abstractmethod
    def get_ticker_price(self, ticker_symbol: str) -> Optional[float]:
        ...

    @abstractmethod
    def get_currency_balance(self, currency_symbol: str) -> float:
        ...

    @abstractmethod
    def get_fee(self, origin_coin: Coin, target_coin: Coin, selling: bool) -> float:
        ...

    @abstractmethod
    def get_min_notional(self, origin_symbol: str, target_symbol: str) -> float:
        ...

    @abstractmethod
    def buy_alt(self, origin_coin: Coin, target_coin: Coin):
        ...

    @abstractmethod
    def sell_alt(self, origin_coin: Coin, target_coin: Coin):
        ...
